toolbar.code:
.root {
  position: sticky;
  top: 0;
  z-index: 4;
  box-sizing: border-box;
  width: 100%;
  flex: none;
  min-height: var(--dsh-trajectory-toolbar-height);
  border-bottom: 0.5px solid var(--dsw-alias-border-l2);
  background: var(--dsw-alias-bg-layer-1);
}

.inner {
  display: flex;
  align-items: center;
  box-sizing: border-box;
  width: 100%;
  min-height: var(--dsh-trajectory-toolbar-height);
  flex-wrap: wrap;
  padding: 4px 6px;
  gap: 4px 8px;
}

.actions {
  display: flex;
  flex: 0 1 auto;
  flex-wrap: wrap;
  min-width: 0;
  align-items: center;
  gap: 2px;
}

.toggle {
